// @ts-check

/**
 * Two sidebars, see OUTLINE.md §2.3:
 * - guideSidebar: docs/intro.md + docs/guide/** + glossary
 * - devSidebar:   docs/develop/** (develop/index first) + glossary as a ref,
 *   so the glossary keeps a single owning sidebar for prev/next navigation.
 *
 * develop/index is filtered out of the autogenerated items in
 * docusaurus.config.js (sidebarItemsGenerator) to avoid listing it twice.
 */

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
const sidebars = {
  guideSidebar: [
    'intro',
    {type: 'autogenerated', dirName: 'guide'},
    'glossary',
  ],
  devSidebar: [
    'develop/index',
    {type: 'autogenerated', dirName: 'develop'},
    {type: 'ref', id: 'glossary'},
  ],
};

export default sidebars;
